      "tooltip": "Performance-based metrics are like a balance scale, they measure the weight of actual results rather than the abstract quality of the internal process."
    }
  ],
  "claim_sketches": [
    {
      "claim": "The right to superior outcomes must supersede the demand for human-understandable explanations in high-stakes fields like medicine and climate science.",
      "targets": []
    },
    {
      "claim": "Forcing advanced AI to conform to human cognitive constraints is a regressive tax on scientific progress that sacrifices life-saving efficacy for the sake of administrative simplicity.",
      "targets": []
    },
    {
      "claim": "Robust behavioral testing of AI outcomes offers a superior mechanism for public safety compared to the subjective and restrictive goal of internal model transparency.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "The complexity of high-performance models is inextricably linked to their opacity.",
      "if_wrong": "If we could achieve state-of-the-art performance with fully interpretable models, my opposition to transparency mandates would be moot."
    },
